  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Demander au boucher un morceau de bœuf à braiser désossé et paré — paleron, macreuse, joue ou gîte conviennent tous — et compter 1,2 kg de chair nette pour six. Le détailler en cubes de 60 à 70 g, puis les éponger : une viande humide bouillit au lieu de dorer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire chauffer le beurre dans une cocotte en fonte et colorer les cubes par petites fournées, sur toutes leurs faces. Les réserver dans un plat creux avec le jus qu''ils rendent — il repartira dans la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Émincer les oignons et les laisser fondre vingt bonnes minutes dans la graisse de saisie, à feu modéré, jusqu''à ce qu''ils prennent une couleur blonde et se défassent. C''est cette compotée qui fait le corps de la carbonade : l''écourter donne une sauce maigre que rien ne rattrape ensuite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Saupoudrer les oignons de farine, remuer une minute pour la faire roussir, puis ajouter la cassonade et le vinaigre. Laisser caraméliser quelques secondes, puis verser la bière en raclant le fond de la cocotte pour décoller les sucs.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Remettre la viande et son jus, saler, poivrer, glisser le thym et le laurier. Tartiner les tranches de pain d''épices de moutarde et les poser côté moutarde à la surface du liquide, sans les enfoncer : elles se déferont d''elles-mêmes et lieront la sauce en cours de cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrir et laisser mijoter deux heures trente à trois heures à très petit feu, ou au four à 150 °C. Le liquide doit à peine frémir : une ébullition franche resserre les fibres au lieu de les fondre, et la viande reste ferme quelle que soit la durée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Découvrir, remuer pour incorporer complètement le pain d''épices, et laisser réduire dix minutes si la sauce reste liquide. Goûter et rééquilibrer : une pointe de vinaigre si le sucre domine, une pointe de cassonade si l''amertume de la bière ressort trop.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Retirer le thym et le laurier, puis laisser reposer la cocotte hors du feu un quart d''heure avant de servir. La carbonade est meilleure réchauffée le lendemain, quand la sauce a fini de prendre et que l''amer de la bière s''est arrondi.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'FR-003', 'recipe_family', 'Carbonade flamande',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'FR-003', 'missing_required_count', v_missing), 'open');
  END IF;

