  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Nettoyer les champignons à sec, au pinceau ou dans un linge humide, puis les couper en quartiers. Passés sous l''eau du robinet ils la boivent et la rendront ensuite dans la sauce, qu''ils délaveraient. Émincer les échalotes finement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Détailler les blancs de poulet en aiguillettes épaisses ou en gros cubes, les éponger et les saler légèrement. Chauffer l''huile dans une sauteuse large et les colorer deux minutes par face à feu vif, sans chercher à les cuire à cœur : ils finiront leur cuisson dans la sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Réserver le poulet sur une assiette. Jeter les champignons dans la sauteuse chaude, sans ajouter de matière grasse, et les laisser rendre leur eau à feu vif. Attendre que le liquide se soit évaporé et qu''ils grésillent en prenant couleur : un champignon doré donne du goût, un champignon bouilli n''en donne aucun.');

