     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Pizza margherita maison', 'Pâte levée garnie d''une sauce tomate et mozzarella fraîche, cuite à haute température', ds.id, 'IT-007',
    'Myko', 'editorial', 4, 40, 15, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '8e714fbd0d3e37d746700a4819ce8e6a',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":4,"heat":1,"pungency":2,"richness":3,"freshness":3,"intensity":4}'::jsonb, ARRAY['tomate','herbacé','acidulé']::text[],
