    ARRAY['Farine de blé type 00','Eau','Levure boulangère sèche','Sel fin']::text[], ARRAY['conserver_les_ingrédients_signatures','conserver_la_technique_centrale','ne_pas_remplacer_par_un_simple_équivalent_nutritionnel']::text[],
    ARRAY['pétrissage','fermentation','façonnage','cuisson haute température']::text[], ARRAY['Pâte maturée 24 h au froid','légumes grillés']::text[], ARRAY['gluten','lait']::text[],
    'À consommer immédiatement ; pâte crue 48 h au froid.', false, '[]'::jsonb,
