  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Peler les oignons et les émincer en demi-lunes fines et régulières ; prévoir environ 800 g d''oignons entiers à l''achat pour arriver aux 720 g épluchés déclarés ici. Des lamelles d''épaisseur égale colorent ensemble, des lamelles inégales donnent du brûlé et du cru dans le même bol.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire fondre le beurre dans une cocotte à fond épais, y verser les oignons avec le thym et la feuille de laurier, couvrir et laisser rendre l''eau dix minutes à feu doux. Ne pas saler à ce stade : le sel appelle l''eau vers l''extérieur et retarde d''autant la coloration.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Découvrir et poursuivre vingt minutes à feu moyen en remuant régulièrement et en raclant le fond, jusqu''à une teinte d''acajou uniforme. Toute la soupe est là : cette caramélisation lente ne se remplace par aucune cuisson vive, qui ne donnerait que du brûlé et de l''amertume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Poudrer les oignons de farine et la travailler une minute pour lui faire perdre son cru, puis déglacer au vin blanc en grattant les sucs collés au fond de la cocotte et laisser réduire presque à sec avant de mouiller.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser le bouillon de volaille chaud, porter au frémissement et laisser mijoter dix minutes à découvert. Rectifier seulement maintenant en sel et en poivre : le bouillon a réduit et sa salinité s''est concentrée, saler avant reviendrait à saler deux fois.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Pendant ce temps, tailler le pain de campagne en tranches d''un bon centimètre et les faire sécher au four à chaleur douce jusqu''à ce qu''elles croustillent sans brunir, puis frotter chaque tranche encore tiède avec une gousse d''ail coupée. Une tranche qui n''a pas séché se délite dans le bouillon et le gratin s''effondre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Répartir la soupe dans des bols à gratin, poser une tranche de pain par bol, la couvrir généreusement de gruyère râpé et passer sous le gril cinq minutes, jusqu''à ce que le fromage boursoufle et se tache de brun. Servir aussitôt, tant que la croûte résiste encore à la cuillère.');

  INSERT INTO quality.review_tasks
