  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Parer les champignons : couper le bout terreux des pieds et essuyer les chapeaux avec un linge humide plutôt que de les passer sous l''eau, qui les gorge et emporte le parfum. Compter environ 800 g bruts pour les 750 g parés déclarés ici.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Réserver une petite poignée des plus fermes pour la garniture et émincer le reste en lamelles, puis arroser aussitôt la masse émincée du jus de citron. Sans cet acide, les lames noircissent en quelques minutes et le velouté vire au gris sale.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire fondre 20 g du beurre dans une sauteuse large, y laisser suer l''oignon haché et l''ail écrasé cinq minutes sans coloration, puis ajouter les champignons émincés et monter le feu. Ils rendent d''abord beaucoup d''eau : il faut la laisser s''évaporer entièrement avant qu''ils commencent à dorer, sinon ils bouillent au lieu de concentrer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dans une casserole à part, cuire les 60 g de beurre restants avec la farine deux minutes en remuant pour obtenir un roux à peine blond — il faut à peu près autant de gras que de farine, un roux trop sec restant sableux et refusant le lait, puis verser le lait froid en trois fois en fouettant à chaque ajout. Terminer par le bouillon de volaille et laisser épaissir cinq minutes à feu doux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Réunir les champignons et leur jus au velouté, râper la muscade, couvrir et laisser mijoter quinze minutes à petit feu. C''est le temps dont le champignon a besoin pour céder son goût au liquide ; en dessous, la soupe reste laiteuse et le champignon garde tout pour lui.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Mixer longuement, deux bonnes minutes, puis passer au chinois pour une texture parfaitement soyeuse. Incorporer la crème hors du feu, rectifier en sel et en poivre — la crème arrondit et masque, il faut donc goûter après elle et non avant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Poêler les champignons réservés, coupés en quartiers, à sec dans une poêle bien chaude jusqu''à ce qu''ils dorent en restant fermes. Les répartir sur les assiettes avec le persil haché et servir sans attendre, la garniture ramollissant vite au contact du velouté chaud.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'FR-013', 'recipe_family', 'Velouté de champignons',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'FR-013', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
