    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Chef Simon lie le velouté hors du feu de deux jaunes d''œuf battus avec la crème : la texture s''épaissit sans farine supplémentaire, mais toute ébullition est ensuite interdite.','Une page chefsimon déglace les champignons de 10 cl de vin blanc sec avant de mouiller, ce qui apporte une acidité plus franche que le citron.','La version express de marmiton part de 460 g de champignons de Paris en boîte égouttés, remplace le lait par 25 cl de crème liquide et lie au pain sec émietté.','Deux pages se passent de roux et lient le velouté d''une pomme de terre cuite avec les champignons puis mixée avec eux.','750g monte un velouté aux champignons des bois où les champignons de Paris cèdent la place à des sauvages, relevés de poudre de chili, de gingembre râpé et de paprika fumé.','Deux cuillerées à café de madère ajoutées en fin de cuisson, en option chez marmiton.','Une page chefsimon monte le même velouté sur une base de poireaux et de gingembre frais, les champignons n''y étant plus qu''une garniture poêlée avec du bacon grillé.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"FR-013","variants":["Chef Simon lie le velouté hors du feu de deux jaunes d''œuf battus avec la crème : la texture s''épaissit sans farine supplémentaire, mais toute ébullition est ensuite interdite.","Une page chefsimon déglace les champignons de 10 cl de vin blanc sec avant de mouiller, ce qui apporte une acidité plus franche que le citron.","La version express de marmiton part de 460 g de champignons de Paris en boîte égouttés, remplace le lait par 25 cl de crème liquide et lie au pain sec émietté.","Deux pages se passent de roux et lient le velouté d''une pomme de terre cuite avec les champignons puis mixée avec eux.","750g monte un velouté aux champignons des bois où les champignons de Paris cèdent la place à des sauvages, relevés de poudre de chili, de gingembre râpé et de paprika fumé.","Deux cuillerées à café de madère ajoutées en fin de cuisson, en option chez marmiton.","Une page chefsimon monte le même velouté sur une base de poireaux et de gingembre frais, les champignons n''y étant plus qu''une garniture poêlée avec du bacon grillé."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:FR-013', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ce0bcd27f30e71f21e4668946b0e9faf'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":1,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["champignon terreux","lait et crème","beurre","oignon fondu"],"aroma_families":["champignon","lacté","beurre","persil frais"],"target_textures":["velouté lisse","nappant","sans fibre","champignons poêlés fermes"],"signature_ingredients":["Champignon de Paris frais","Lait entier","Crème fraîche liquide entière"],"identity_guardrails":["Le champignon doit rester l''ingrédient dominant en masse : dès qu''un autre légume prend le dessus — poireau, pomme de terre, carotte — le velouté change de nom, comme le montrent les deux titres dérivants du dossier.","Le liquide est lacté : remplacer entièrement le lait par de l''eau ou du bouillon donne une soupe de champignons, pas un velouté.","Les champignons doivent avoir rendu puis évaporé leur eau avant le mouillement ; noyés trop tôt, ils bouillent au lieu de concentrer et le velouté reste plat.","La texture doit être entièrement mixée et sans fibre : des lamelles laissées entières en feraient une soupe rustique."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;
DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Velouté de potimarron', 'veloute de potimarron', 'France', 'France',
     'meal', 'soupe', 'domestic_standard', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Velouté de potimarron', 'Potimarron fondu au bouillon, mixé en velouté et lié à la crème fraîche avec une touche de muscade', ds.id, 'FR-014',
    'Myko', 'editorial', 6, 20, 30, 'facile',
    NULL, NULL,
    'B', 'candidate', '4df198d72591dcf495474de1c09e98f8',
    '{"sweet":3,"salty":2,"acidic":0,"bitter":0,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":2}'::jsonb, ARRAY['potimarron sucré','crème lactée','beurre','muscade']::text[],
    ARRAY['courge','lacté','beurre','muscade']::text[], ARRAY['velouté lisse','nappant','sans fibre']::text[],
    ARRAY['Potimarron frais, épépiné','Crème fraîche liquide entière','Bouillon de légumes']::text[], ARRAY['Le potimarron reste seul en scène, à 200 g de chair par portion : l''adjonction massive de carotte, de pomme de terre ou de panais en fait un autre velouté.','La peau ne s''enlève pas : c''est ce qui distingue le potimarron d''une courge à éplucher, et son parfum de châtaigne en dépend.','L''oignon doit suer sans coloration ; une base caramélisée écrase la douceur qui est tout l''intérêt du plat.','La crème s''incorpore hors du feu, en finition, et jamais en début de cuisson.']::text[],
    ARRAY['parage','suer','cuisson au bouillon','mixage','liaison']::text[], ARRAY['Deux pages du dossier, une marmiton et une chefsimon, ajoutent 200 g de châtaignes cuites au mouillement : le velouté s''épaissit et la note de châtaigne double. La forme n''existe pas au catalogue et la variante reste une indication tant qu''elle n''est pas arbitrée.','Une page marmiton complète le potimarron de quatre carottes et de trois pommes de terre, ce qui donne un velouté plus dense, plus terreux et moins sucré.','Chef Simon marie le potimarron à un gros panais, mouillé simplement à l''eau et à deux cubes de bouillon de légumes.','Une page chefsimon parfume le velouté d''une dizaine de pistils de safran, d''une cuillerée à café de cumin en poudre et d''un trait de jus d''orange, et remplace la crème par de la crème de soja.','Marmiton mouille au lait entier plutôt qu''au bouillon, après l''avoir infusé de deux clous de girofle, de grains de poivre noir et de lamelles de gingembre frais, et termine chaque assiette de ciboulette ciselée.','750g monte la crème liquide en chantilly non sucrée et en dépose une cuillerée sur chaque assiette au moment de servir ; une autre page y ajoute des morilles séchées réhydratées.','L''échalote remplace l''oignon sur deux des huit pages ; ailleurs le beurre cède la place à l''huile d''olive, à l''huile de colza ou à l''huile de noisette, une page chacune.']::text[], ARRAY['lait']::text[],
    'Se garde quatre jours au réfrigérateur entre 0 et 4 °C dans un contenant fermé, et se réchauffe à feu doux sans ébullition pour que la crème ne tranche pas. Le potimarron supporte très bien la congélation : congeler la base mixée non crémée jusqu''à quatre mois et n''incorporer la crème qu''au réchauffage, une base congelée déjà crémée se déphasant et rendant le velouté granuleux. Le velouté s''épaissit en refroidissant, prévoir un peu de bouillon pour le détendre au réchauffage.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
