      WHERE ff.canonical_name_normalized = 'potimarron frais epepine' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Potimarron frais, épépiné', 1200, 'g', 'required',
     'base', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
