  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Laver le potimarron, le fendre en deux et retirer à la cuillère les graines et les filaments. Ne pas l''éplucher : sa peau fine cuit et se mixe sans laisser de fibre, et elle porte une part du goût de châtaigne qui fait la réputation de cette courge. Compter un fruit d''environ 1,4 kg entier pour arriver aux 1200 g épépinés déclarés ici.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Détailler la chair en cubes de deux à trois centimètres, aussi réguliers que possible pour qu''ils cuisent ensemble, puis hacher finement l''oignon et écraser l''ail du plat du couteau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire fondre le beurre dans une cocotte et y laisser suer l''oignon et l''ail cinq à six minutes à feu doux, sans les laisser prendre couleur. La moindre caramélisation apporterait une amertume qui se remarque immédiatement dans un velouté aussi doux que celui-ci.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Ajouter les cubes de potimarron, les enrober de beurre deux minutes en remuant, puis mouiller avec le bouillon de légumes chaud juste à hauteur. Un mouillement qui noie les cubes dilue le goût et oblige à réduire ensuite pour rien : mieux vaut en garder un peu de côté pour détendre à la fin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Couvrir et laisser cuire vingt-cinq à trente minutes à petits bouillons, jusqu''à ce qu''un cube s''écrase sans résistance sous le dos d''une cuillère. Râper la muscade dans les dernières minutes, à chaud : jetée à froid dans un velouté déjà mixé, elle reste poudreuse et se sent à part du reste.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Mixer très finement, deux bonnes minutes, jusqu''à une texture lisse et nappante, en ajoutant un peu du bouillon réservé si le velouté s''est trop resserré. Incorporer la crème hors du feu, rectifier en sel et en poivre et servir bien chaud en assiette creuse.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'FR-014', 'recipe_family', 'Velouté de potimarron',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'FR-014', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
