  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Croque-monsieur en gratin : pain remplacé par des biscottes, noyées dans un litre de béchamel pour six et gratinées en plat (750g.com)','Croque-monsieur d''aubergines : tranches d''aubergine à la place du pain, avec tomate, crème et moutarde — un homonyme plutôt qu''une variante (marmiton.org)','Crème épaisse étalée à cru à la place de la béchamel, sans roux (marmiton.org) — la crème liquide, elle, n''apparaît que dans le croque d''aubergines','Un simple filet de lait sur le pain, sans sauce — quatre cuillerées à soupe pour deux croques, ou une cuisson à l''airfryer (chefsimon.com, deux sources)','Emmental râpé ou comté râpé à la place du gruyère (trois sources)','Crème de champignons au parmesan en remplacement de la béchamel (chefsimon.com)','Une pointe de moutarde : le dossier ne la porte que dans le croque d''aubergines, où elle est étalée sur le légume et non sur du pain (marmiton.org)','Pain de mie maison à l''ail des ours, et origan ou herbes de Provence sur le fromage (chefsimon.com, marmiton.org)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"FR-023","variants":["Croque-monsieur en gratin : pain remplacé par des biscottes, noyées dans un litre de béchamel pour six et gratinées en plat (750g.com)","Croque-monsieur d''aubergines : tranches d''aubergine à la place du pain, avec tomate, crème et moutarde — un homonyme plutôt qu''une variante (marmiton.org)","Crème épaisse étalée à cru à la place de la béchamel, sans roux (marmiton.org) — la crème liquide, elle, n''apparaît que dans le croque d''aubergines","Un simple filet de lait sur le pain, sans sauce — quatre cuillerées à soupe pour deux croques, ou une cuisson à l''airfryer (chefsimon.com, deux sources)","Emmental râpé ou comté râpé à la place du gruyère (trois sources)","Crème de champignons au parmesan en remplacement de la béchamel (chefsimon.com)","Une pointe de moutarde : le dossier ne la porte que dans le croque d''aubergines, où elle est étalée sur le légume et non sur du pain (marmiton.org)","Pain de mie maison à l''ail des ours, et origan ou herbes de Provence sur le fromage (chefsimon.com, marmiton.org)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:FR-023', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('6fe95bfea4512dbec0e2e833d9332e73'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":4,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":0,"intensity":3},"dominant_flavors":["fromage_fondu","jambon_cuit","beurre","muscade"],"aroma_families":["beurre","gruyère","pain_grillé","muscade"],"target_textures":["croûte_gratinée","mie_moelleuse","cœur_fondant"],"signature_ingredients":["Pain de mie","Jambon blanc cuit","Gruyère râpé"],"identity_guardrails":["Sans pain de mie, ce n''est plus un croque-monsieur : la version montée sur des tranches d''aubergine que porte le dossier est un homonyme, et le nom ne suit pas l''ingrédient.","Le jambon cuit et le fromage fondant vont par paire ; retirer le jambon donne un croque au fromage, qui porte un autre nom et n''a plus la même part de protéine.","La sauce blanche doit napper le pain dessus et dedans : réduite à un filet de lait, le croque sort sec et devient un toast grillé, ce que deux sources assument d''ailleurs comme une recette distincte."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
