  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Choisir une variété farineuse — bintje, agria, ou une pomme de terre vendue pour la purée. Une chair ferme ne s''écrase pas : elle se déchire en filaments et donne une purée à la fois grumeleuse et collante, défaut qu''aucune quantité de beurre ne rattrape ensuite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Compter 1 kg de pommes de terre à l''achat pour les 850 g de chair annoncés. Les peler, les couper en gros morceaux de calibre égal afin qu''ils cuisent en même temps, et les rincer une seule fois rapidement : un rinçage prolongé emporte l''amidon de surface dont la purée a besoin pour se lier.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Les couvrir largement d''eau froide salée, porter à ébullition puis maintenir un frémissement vingt à vingt-cinq minutes. Le départ à froid n''est pas une coquetterie : jetés dans l''eau bouillante, les morceaux se délitent en surface avant que le cœur soit cuit. La pointe d''un couteau doit traverser sans aucune résistance.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Égoutter, puis remettre les morceaux dans la casserole vide sur feu doux une à deux minutes en les remuant. La vapeur qui s''échappe est autant d''eau en moins dans la purée, et c''est ce dessèchement qui décide de sa tenue bien plus que le dosage du lait.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Écraser au presse-purée ou passer au moulin à légumes, grille fine. Ne jamais employer de mixeur plongeant ni de robot : les lames font éclater les grains d''amidon, qui libèrent leurs longues chaînes et transforment la purée en pâte élastique en quelques secondes, sans retour possible.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Incorporer le beurre froid coupé en morceaux, hors du feu et avant tout liquide, en travaillant à la spatule. Froid, il émulsionne dans la chaleur de la pomme de terre au lieu de fondre en flaque grasse, et c''est de cette émulsion que vient le velouté.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Verser ensuite le lait bien chaud en trois fois, en travaillant entre chaque ajout, puis la crème. Un liquide froid figerait le beurre déjà incorporé et rendrait l''ensemble grumeleux : la température compte autant que la quantité.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Râper la muscade, rectifier le sel et le poivre, et servir sans attendre. Une purée qui patiente au chaud rend de l''eau et se rattrape mal ; si vous devez la tenir, couvrez-la au contact et remontez-la d''un filet de lait chaud au dernier moment.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'FR-025', 'recipe_family', 'Purée de pommes de terre',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'FR-025', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Purée à l''ail : quatre gousses cuites avec les pommes de terre, crème liquide et une cuillerée de moutarde à l''ancienne (Marmiton)','Purée à l''ail confit : une tête entière confite écrasée dans la purée, persil haché à la fin (Chef Simon)','Purée moitié fenouil : deux bulbes braisés pour six pommes de terre, crème épaisse (Marmiton)','Purée de pommes de terre et carottes, à parts égales, montée au lait (750g)','Version en cocotte au beurre demi-sel, fond de bœuf et ciboulette (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"FR-025","variants":["Purée à l''ail : quatre gousses cuites avec les pommes de terre, crème liquide et une cuillerée de moutarde à l''ancienne (Marmiton)","Purée à l''ail confit : une tête entière confite écrasée dans la purée, persil haché à la fin (Chef Simon)","Purée moitié fenouil : deux bulbes braisés pour six pommes de terre, crème épaisse (Marmiton)","Purée de pommes de terre et carottes, à parts égales, montée au lait (750g)","Version en cocotte au beurre demi-sel, fond de bœuf et ciboulette (750g)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:FR-025', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('0d6255cee3eaee200a153353b00a0085'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":1,"heat":0,"pungency":0,"richness":5,"freshness":0,"intensity":2},"dominant_flavors":["beurre","pomme de terre","lait chaud"],"aroma_families":["lacté","beurre","muscade"],"target_textures":["velouté","lisse","souple à la cuillère"],"signature_ingredients":["Pomme de terre crue, épluchée","Beurre doux","Lait entier"],"identity_guardrails":["Une variété farineuse et un écrasement mécanique, jamais de lame : passée au robot, la préparation devient une colle élastique qui n''est plus une purée.","Le beurre entre avant le liquide et à froid ; versé après le lait, il ne s''émulsionne plus et la purée reste grasse au palais au lieu d''être veloutée.","La proportion d''un dixième de beurre pour la pomme de terre est ce qui distingue la purée de la pomme de terre écrasée : divisée par trois, il ne reste qu''un légume mouillé."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
