DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Cake jambon et olives', 'cake jambon et olives', 'France — cuisine domestique', 'France — cuisine domestique',
     'meal', 'cake salé', 'domestic_standard', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Cake jambon et olives', 'Cake salé au jambon blanc, olives vertes et gruyère, cuit au four', ds.id, 'FR-028',
    'Myko', 'editorial', 6, 15, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '67212916b08f08129620f4857a5b38b6',
    '{"sweet":1,"salty":4,"acidic":1,"bitter":2,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['olive_saumurée','jambon_cuit','fromage_fondu']::text[],
    ARRAY['olive_verte','gruyère','mie_dorée']::text[], ARRAY['mie_moelleuse','garniture_en_dés','croûte_dorée']::text[],
    ARRAY['Jambon blanc cuit','Olive verte dénoyautée','Gruyère râpé']::text[], ARRAY['Sans olives, il ne reste qu''un cake au jambon : c''est leur point de sel et leur amertume qui donnent au plat son nom et sa mâche, et six sources sur huit les prennent vertes et dénoyautées.','Sans jambon, c''est un cake aux olives, autre plat et autre part de protéine ; le jambon se taille en dés visibles à la coupe, pas en lanières qui disparaissent dans la mie.','La levure chimique n''est pas négociable : les huit sources en mettent un sachet, et sans elle un appareil aussi chargé de garniture sort compact.']::text[],
    ARRAY['appareil à cake salé','enrobage de la garniture à la farine','cuisson au four','démoulage à tiède']::text[], ARRAY['Vin blanc sec à la place du lait, 10 à 15 cl (chefsimon.com, 750g.com)','Beurre fondu, 125 g, à la place de l''huile d''olive (marmiton.org)','Comté en cubes ou râpé à la place du gruyère (marmiton.org, 750g.com)','Olives noires de Kalamata et tomates semi-séchées à l''huile (chefsimon.com)','Moutarde dans l''appareil, d''une cuillère à café à trois cuillères à soupe (marmiton.org, 750g.com)','Thym en feuilles ou persil haché dans la pâte (chefsimon.com, marmiton.org)','Trois blancs de poireau émincés et fondus ajoutés à la garniture (750g.com)','Version sans gluten : moitié farine de riz, moitié maïzena, levure sans gluten, et une pointe de curcuma pour la couleur (marmiton.org)','Mélange de graines parsemé sur le dessus avant cuisson (chefsimon.com)','Cuisson en machine à pain, programme cake, 45 minutes (750g.com)']::text[], ARRAY['gluten','lait','œuf']::text[],
    'Quatre jours au réfrigérateur, enveloppé serré dans du film ou du papier d''aluminium : à l''air libre la mie sèche en une demi-journée. Il se tranche mieux le lendemain, quand la mie a fini de se serrer autour de la garniture. Se congèle trois mois, entier ou en tranches séparées par du papier cuisson — les tranches se réchauffent alors sans décongélation, dix minutes à 150 °C, ce qui rend le moelleux bien mieux que le micro-ondes, qui le rend caoutchouteux. Se sert tiède ou froid, jamais brûlant : à chaud le gras du fromage domine et les olives deviennent amères.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
