     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 3, 'g', 'required',
     'assaisonnement', false, 9);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'required',
     'assaisonnement', false, 10);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Préchauffer le four à 180 °C et chemiser un moule à cake de vingt-quatre centimètres de papier cuisson, ou le huiler au pinceau avec un peu de l''huile pesée. Un cake salé colle plus qu''un cake sucré : la garniture fond au contact des parois et le démoulage arrache la mie si rien ne la protège.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Tailler le jambon en dés d''un centimètre, égoutter les olives et les éponger dans un linge, puis les couper en deux dans la longueur. Les olives sortent du bocal chargées de saumure ; non essuyées, elles mouillent l''appareil par endroits et laissent des poches grises dans la mie. Si elles sont très salées, les rincer à l''eau froide et les sécher à nouveau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Mélanger au fouet la farine et la levure dans un grand saladier, en réservant une cuillerée à soupe de farine à part. Creuser un puits, y casser les œufs et les incorporer un à un, puis verser le lait et l''huile en filet sans cesser de tourner, jusqu''à obtenir une pâte lisse et coulante. S''arrêter dès qu''elle est homogène : plus on la travaille, plus le gluten se développe et plus la mie sortira élastique.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Rouler les olives dans la cuillerée de farine réservée, puis ajouter à l''appareil les olives, les dés de jambon et le gruyère. Poivrer et ne saler que de trois grammes : le jambon, les olives saumurées et le fromage apportent déjà l''essentiel du sel, et un cake trop salé ne se rattrape pas. Mélanger à la spatule en repliant la pâte, le temps que la garniture soit partout enrobée — c''est cet enrobage qui l''empêche de tomber au fond pendant la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser dans le moule, égaliser la surface à la spatule et enfourner quarante-cinq minutes à 180 °C. Ne pas ouvrir la porte avant la trentième minute : l''appareil, lourd de garniture, ne tient sa levée que par la chaleur constante, et un courant d''air le fait retomber au centre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Vérifier la cuisson en plantant la pointe d''un couteau au cœur : elle doit ressortir sèche, sans trace de pâte crue. Sortir le cake, attendre dix minutes, démouler sur une grille et le laisser tiédir complètement avant de le trancher. Coupé chaud, il s''effrite et les olives déchirent la tranche ; froid ou juste tiède, il se coupe net.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
