  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:FR-028', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('67212916b08f08129620f4857a5b38b6'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":4,"acidic":1,"bitter":2,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["olive_saumurée","jambon_cuit","fromage_fondu"],"aroma_families":["olive_verte","gruyère","mie_dorée"],"target_textures":["mie_moelleuse","garniture_en_dés","croûte_dorée"],"signature_ingredients":["Jambon blanc cuit","Olive verte dénoyautée","Gruyère râpé"],"identity_guardrails":["Sans olives, il ne reste qu''un cake au jambon : c''est leur point de sel et leur amertume qui donnent au plat son nom et sa mâche, et six sources sur huit les prennent vertes et dénoyautées.","Sans jambon, c''est un cake aux olives, autre plat et autre part de protéine ; le jambon se taille en dés visibles à la coupe, pas en lanières qui disparaissent dans la mie.","La levure chimique n''est pas négociable : les huit sources en mettent un sachet, et sans elle un appareil aussi chargé de garniture sort compact."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
