  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Gougères aux trois fromages : mimolette, gouda et emmental à parts égales à la place du gruyère (marmiton.org)','Parmesan et fromage de chèvre basque, 150 g et 50 g (chefsimon.com)','Comté râpé à la place du gruyère, la source donnant les deux comme équivalents (chefsimon.com)','Moitié eau, moitié lait entier dans la panade, pour une coque plus tendre (750g.com)','Pointe de piment de Cayenne ou de piment d''Espelette à la place du poivre (750g.com, marmiton.org)','Thym ou ciboulette hachée dans la pâte (marmiton.org)','Mélange de graines sur le dessus et pâte pochée en bâtonnets, cuits douze minutes (750g.com)','Beignets de gougères : la même pâte, plus fluide et frite au lieu d''être cuite au four (marmiton.org)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"FR-031","variants":["Gougères aux trois fromages : mimolette, gouda et emmental à parts égales à la place du gruyère (marmiton.org)","Parmesan et fromage de chèvre basque, 150 g et 50 g (chefsimon.com)","Comté râpé à la place du gruyère, la source donnant les deux comme équivalents (chefsimon.com)","Moitié eau, moitié lait entier dans la panade, pour une coque plus tendre (750g.com)","Pointe de piment de Cayenne ou de piment d''Espelette à la place du poivre (750g.com, marmiton.org)","Thym ou ciboulette hachée dans la pâte (marmiton.org)","Mélange de graines sur le dessus et pâte pochée en bâtonnets, cuits douze minutes (750g.com)","Beignets de gougères : la même pâte, plus fluide et frite au lieu d''être cuite au four (marmiton.org)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:FR-031', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('2d6bce8c62a220c7ca1302827a34b6f6'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":0,"intensity":3},"dominant_flavors":["fromage_affiné","beurre","muscade"],"aroma_families":["beurre","gruyère","pâte_à_choux"],"target_textures":["coque_croustillante","intérieur_creux","mie_soufflée"],"signature_ingredients":["Gruyère râpé","Beurre doux","Œuf cru","Farine de blé T55"],"identity_guardrails":["Sans fromage, ce sont des choux salés et non des gougères : les neuf sources en mettent en moyenne 100 g pour 100 g de farine, autant que la farine elle-même.","La panade doit être desséchée sur le feu avant les œufs ; sans ce passage la pâte ne gonfle pas et on obtient des galettes, quelle que soit la température du four.","Le fromage est râpé et incorporé dans la pâte, pas seulement parsemé dessus : la gougère est creuse, et si le goût n''est pas dans la coque il n''est nulle part."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
