      ('sensory_contract', '{"profile":"sweet_spiced","scores":{"sweet":5,"salty":1,"acidic":1,"bitter":1,"umami":1,"heat":1,"pungency":2,"richness":4,"freshness":2,"intensity":4},"dominant_flavors":["sucré","beurré","épices douces"],"aroma_families":["beurre","vanille"],"target_textures":["dessus_doré","intérieur_fondant_ou_crémeux"],"signature_ingredients":["Pomme fraîche","Pâte feuilletée crue","Sucre semoule","Beurre doux"],"identity_guardrails":["conserver_les_ingrédients_signatures","conserver_la_technique_centrale","ne_pas_remplacer_par_un_simple_équivalent_nutritionnel"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
