  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Compter quatre à cinq cuisses de canard confites, soit environ 1,3 kg brut, pour obtenir les 650 g de chair annoncés : l''os et la graisse pèsent près de la moitié d''une cuisse. Les sortir de leur graisse et les poser dans un plat, côté peau vers le haut, puis les tiédir vingt minutes à four doux — 130 °C suffisent. La graisse se liquéfie et la chair se détache alors sans forcer, ce qu''on n''obtient pas sur un confit sorti du froid.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Éplucher les pommes de terre — prévoir les 950 g du dossier avant épluchage pour obtenir les 810 g déclarés — et les couper en morceaux réguliers, de la taille d''une grosse noix. Les couvrir d''eau froide salée, porter à ébullition et laisser cuire vingt à vingt-cinq minutes, jusqu''à ce que la lame d''un couteau traverse sans résistance. Démarrer à froid plutôt qu''à l''eau bouillante fait cuire le cœur et la surface au même rythme : c''est ce qui évite les morceaux délités au bord et fermes au centre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant cette cuisson, désosser les cuisses tièdes : retirer l''os, la peau si on la juge trop grasse, et effiler la chair aux doigts en filaments plutôt qu''au couteau en cubes — la fibre du confit se sépare naturellement, et c''est ce qui donne au parmentier sa texture filandreuse. Prélever deux cuillerées de la graisse de confit et les réserver ; le reste se garde au réfrigérateur pour d''autres usages.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Chauffer la graisse réservée dans une sauteuse et y faire fondre les oignons finement émincés à feu moyen pendant une dizaine de minutes, sans les colorer : on cherche leur sucre, pas leur amertume. Ajouter l''ail haché, laisser prendre l''odeur une minute à peine, puis verser la chair effilochée. Réchauffer l''ensemble deux ou trois minutes, ajouter le persil ciselé hors du feu, poivrer généreusement et goûter avant de saler — un confit est déjà salé et la moitié des 8 g prévus peut suffire ici.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Égoutter les pommes de terre et les laisser rendre leur vapeur deux minutes dans la casserole vide, sur le feu éteint : une purée montée sur des pommes de terre encore humides tourne à la colle. Les écraser au presse-purée ou au moulin à légumes, jamais au robot, dont la lame libère l''amidon et rend l''appareil élastique. Incorporer le beurre en parcelles, puis le lait chaud petit à petit jusqu''à obtenir une purée souple qui retombe du fouet en ruban. Râper la muscade, rectifier le sel.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Étaler la garniture de canard au fond d''un plat à gratin d''environ deux litres, en la tassant à peine pour qu''elle reste aérée. Recouvrir de la purée en la déposant à la cuillère par petits tas que l''on relie ensuite, plutôt qu''en l''étalant d''un seul geste : on évite ainsi d''entraîner le canard dans la couche du dessus. Lisser à la fourchette en laissant des sillons — ce sont eux qui dorent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Répartir le comté râpé sur toute la surface et enfourner à 190 °C pour vingt-cinq à trente minutes. Le plat est prêt quand la croûte est franchement brune et que la garniture bouillonne sur les bords. Si le dessus reste pâle alors que le cœur est chaud, passer deux minutes sous le gril en surveillant sans s''éloigner.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Sortir le plat et le laisser reposer dix minutes avant de servir. Ce repos n''est pas une politesse : à la sortie du four les couches glissent l''une sur l''autre et la part s''effondre dans l''assiette, alors qu''après dix minutes elle se découpe nette et garde ses deux étages visibles.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'FR-037', 'recipe_family', 'Parmentier de canard',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'FR-037', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au potiron vanillé, moitié potiron moitié pomme de terre, la purée mouillée au lait de soja (marmiton)','Aux noisettes concassées dans la garniture et au comté sur le dessus (chefsimon)','Aux petits pois écossés et oignons nouveaux à la place de la purée de pomme de terre (chefsimon)','Aux courgettes et panais mêlés à la purée, finition ciboulette (750g)','Garniture déglacée au madère ou au porto et liée d''un fond de canard, montée sur des tranches de pain (chefsimon)','Purée enrichie de crème fraîche en plus du lait (marmiton, chefsimon)','Une pointe de miel dans le canard effiloché (marmiton)','Dessus de chapelure plutôt que de fromage, éventuellement avec un éclat de foie gras dans la garniture (750g)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"FR-037","variants":["Au potiron vanillé, moitié potiron moitié pomme de terre, la purée mouillée au lait de soja (marmiton)","Aux noisettes concassées dans la garniture et au comté sur le dessus (chefsimon)","Aux petits pois écossés et oignons nouveaux à la place de la purée de pomme de terre (chefsimon)","Aux courgettes et panais mêlés à la purée, finition ciboulette (750g)","Garniture déglacée au madère ou au porto et liée d''un fond de canard, montée sur des tranches de pain (chefsimon)","Purée enrichie de crème fraîche en plus du lait (marmiton, chefsimon)","Une pointe de miel dans le canard effiloché (marmiton)","Dessus de chapelure plutôt que de fromage, éventuellement avec un éclat de foie gras dans la garniture (750g)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:FR-037', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('278f3115d38665381cf0d2f3ce150ae5'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"rich_savory","scores":{"sweet":2,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4},"dominant_flavors":["canard confit","beurre","oignon fondu","fromage gratiné"],"aroma_families":["graisse de canard","oignon compoté","croûte grillée","muscade"],"target_textures":["chair filandreuse","purée souple","croûte croustillante"],"signature_ingredients":["Confit de canard cuit, effiloché","Pomme de terre crue, épluchée","Beurre doux"],"identity_guardrails":["Sans confit de canard ce n''est plus qu''un hachis parmentier : la chair effilochée cuite dans sa graisse est le plat lui-même","Deux couches distinctes, garniture dessous et purée dessus — mélangées, c''est une autre préparation","Une croûte dorée au four : un parmentier servi sans gratiner n''est pas fini","Aucune viande hachée crue en remplacement du confit, même à protéines égales"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = '349fe655173914ccfd579fd2e6d29046' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
