    ARRAY['ail','échalote','vin_blanc_réduit','lacté','moutarde','thym']::text[], ARRAY['protéine_fondante','sauce_nappante']::text[],
    ARRAY['Lapin cru, découpé','Moutarde de Dijon','Crème fraîche épaisse','Vin blanc sec']::text[], ARRAY['conserver_les_ingrédients_signatures','conserver_la_technique_centrale','ne_pas_remplacer_par_un_simple_équivalent_nutritionnel']::text[],
    ARRAY['saisie douce','déglaçage','braisage','réduction','finition crème']::text[], ARRAY['Poulet','estragon','champignons']::text[], ARRAY['lait','moutarde']::text[],
    '3 jours au réfrigérateur.', false, '[]'::jsonb,
