  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Enduire légèrement le lapin de moutarde et le saisir sans brûler le condiment.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire suer les échalotes, déglacer au vin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
