     status, confidence_level)
  VALUES
    ('Salade lyonnaise', 'salade lyonnaise', 'France (Lyon)', 'France (Lyon)',
     'meal', 'salade composée', 'named_traditional_dish', 'fresh_acidic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Salade lyonnaise', 'Frisée en vinaigrette moutardée avec lardons dorés, croûtons et un œuf poché', ds.id, 'REAL-087',
    'Myko', 'editorial', 4, 20, 15, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'ebd56eb6b404a588659583ac16481de7',
    '{"sweet":1,"salty":4,"acidic":4,"bitter":3,"umami":3,"heat":0,"pungency":2,"richness":3,"freshness":4,"intensity":3}'::jsonb, ARRAY['amertume de la frisée','vinaigre de vin','lard fumé','moutarde']::text[],
    ARRAY['fumé','vinaigre de vin rouge','moutarde','pain grillé']::text[], ARRAY['feuille croquante','lardon doré','croûton sec','jaune coulant']::text[],
    ARRAY['Frisée fraîche','Lardon fumé cru','Œuf cru']::text[], ARRAY['Une verdure amère : sur une laitue douce, la vinaigrette et le lard n''ont plus rien à équilibrer','Un jaune coulant qui fait sauce quand on le perce — œuf cuit dur, le plat perd sa liaison','Lardons et croûtons ajoutés chauds sur la salade crue : le contraste tiède-cru est le plat','Vinaigrette au vinaigre de vin et à la moutarde, jamais une sauce crémée']::text[],
    ARRAY['lavage et essorage de salade','rendu du gras à sec','croûtons à la graisse de lard','émulsion moutardée','pochage','assaisonnement tiède']::text[], ARRAY['Avec un saucisson lyonnais à cuire, poché et servi en rondelles tièdes sur la salade (marmiton, deux sources)','Cerneaux de noix concassés ajoutés aux croûtons (marmiton)','Une échalote ciselée fondue dans la vinaigrette (chefsimon)','Pissenlits à la place de la frisée, racine ôtée (marmiton, chefsimon)','Batavia ou roquette à la place de la frisée (chefsimon)','Croûtons dorés au beurre plutôt qu''à la graisse de lard (chefsimon)','Une pointe de sauce Maggi dans la vinaigrette (marmiton)']::text[], ARRAY['gluten','moutarde','œuf']::text[],
    'Ne se conserve pas assemblée : la frisée rend son eau et les croûtons ramollissent en moins d''un quart d''heure. Préparer les éléments à l''avance et monter au dernier moment — la frisée lavée tient 2 jours au réfrigérateur dans un linge humide, la vinaigrette 5 jours en bocal, les croûtons 2 jours en boîte hermétique à température ambiante. Les lardons se réchauffent, les œufs pochés se pochent à la commande.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
